#!/usr/bin/env python
import os
import shutil
import fnmatch

# Directories considered junk
JUNK_DIRS = {
    '__pycache__',
    'build',
    'dist',
    'node_modules',
}

# File patterns considered junk
JUNK_PATTERNS = {
    '*~',          # backup files
    '*.tmp',       # temporary files
    '*.log',       # log files
    '*.bak',       # backup files
    '*.swp',       # swap files
    '*.pyc',       # compiled python files
    '*.DS_Store',  # macOS thumbnail files
}

def matches_any(name, patterns):
    return any(fnmatch.fnmatch(name, pat) for pat in patterns)

def cleanup_junk():
    for root, dirs, files in os.walk('.'):
        # Skip .git directory entirely
        if '.git' in root.split(os.sep):
            continue
        # Delete junk directories
        for d in dirs:
            if d in JUNK_DIRS:
                try:
                    shutil.rmtree(os.path.join(root, d))
                    print(f'Removed junk directory: {os.path.join(root, d)}')
                except Exception as e:
                    print(f'Failed to remove directory {d}: {e}')
        # Remove files matching junk patterns
        for f in files:
            if matches_any(f, JUNK_PATTERNS):
                try:
                    os.remove(os.path.join(root, f))
                    print(f'Deleted junk file: {os.path.join(root, f)}')
                except Exception as e:
                    print(f'Failed to delete file {f}: {e}')

if __name__ == '__main__':
    cleanup_junk()

